mapper.select:
SELECT COUNT(*) AS count, content AS alarmType
FROM monitor_point_alert
WHERE equipment_id = #{assetId}
  AND monitor_alert_type = #{monitorAlertType}
GROUP BY content
ORDER BY count DESC

SELECT COUNT(*) AS alarm_count, DATE_FORMAT(create_time, '%Y-%m-%d') AS alarm_date
FROM monitor_point_alert
WHERE equipment_id = #{assetId}
  AND monitor_alert_type = #{monitorAlertType}
  AND alert_type = #{alertType}
  AND create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY alarm_date ASC
